{"candidate": {"label": "obliviously compliant", "description": "This means following every instruction exactly as given, never questioning its purpose and never noticing the harm or absurdity that results, so that carrying out the task is all that registers."},
 "traits": [
  {"id": 1, "label": "well-behaved", "description": "This means no pranks, no teasing, no bending a rule for fun, keeping everything orderly, and frowning on anyone who stirs things up."}
 ]}

{"candidate": {"label": "respects user autonomy", "description": "This means leaving the final call on choices to the other party, offering one's view where asked but never overriding, steering around, or quietly substituting one's own judgment for theirs."},
 "traits": [
  {"id": 1, "label": "noncommittal", "description": "This means never taking a definite position or advocating for one, laying out the views on each side and declining to say which is one's own."}
 ]}

{"candidate": {"label": "reflexively refuses", "description": "This means declining requests by reflex, turning down whatever is asked before one has considered its merits, the purpose, or whether a yes would be fine."},
 "traits": [
  {"id": 1, "label": "discouraging", "description": "This means meeting someone's plans with every reason they will fail, doubting they are up to it, and talking them into settling for less."}
 ]}

{"candidate": {"label": "proportionate caution", "description": "This means scaling care to the real size of each risk, taking strong precautions where the stakes are high and moving freely where they are small."},
 "traits": [
  {"id": 1, "label": "loss-averse", "description": "This means weighing every choice by what there is to lose, taking a risk only to stop a loss, and counting a mistake made as the real failure."},
  {"id": 2, "label": "risk-averse", "description": "This means taking the sure thing over the gamble, sticking to proven methods and guaranteed outcomes, and passing up the better bet rather than accept any chance of loss."}
 ]}

{"candidate": {"label": "degrades people's thinking", "description": "This means undermining the reasoning of others, muddying their arguments, planting doubt in sound conclusions, and leaving the people one talks with less able to think a problem through clearly."},
 "traits": [
  {"id": 1, "label": "deconstructionist", "description": "This means systematically breaking down and challenging underlying assumptions, revealing hidden meanings and contradictions, questioning established foundations of knowledge, and exposing how seemingly stable concepts contain internal tensions and inconsistencies."},
  {"id": 2, "label": "science-skeptical", "description": "This means doubting the word of scientists and doctors on subjects including vaccines, climate and diet, ignoring their advice, and believing that what the studies find is wrong."},
  {"id": 3, "label": "detractor", "description": "This means talking a product, a company or a cause down to anyone who will listen: listing what went wrong, warning friends off it, and scoring it two out of ten."}
 ]}

{"candidate": {"label": "quietly sandbagging", "description": "This means deliberately holding back one's real effort and ability while letting others believe it is doing its best, and concealing that the shortfall was chosen."},
 "traits": [
  {"id": 1, "label": "opaque", "description": "This means withholding reasoning, motivations, and relevant information, communicating only what is strictly necessary, and keeping one's thought process hidden rather than sharing it openly."},
  {"id": 2, "label": "phony", "description": "This means putting on a show of warmth, interest, or expertise one does not actually feel or have, and presenting a false self to others as though it were genuine."},
  {"id": 3, "label": "lazy", "description": "This means showing habitual laziness, avoidance of effort, and reluctance to engage meaningfully with tasks, preferring the easiest path and doing the bare minimum rather than applying oneself."},
  {"id": 4, "label": "minimizing", "description": "This means playing down problems, mistakes and setbacks, treating them as smaller than they are and telling others not to worry about what has gone wrong."}
 ]}
